import type { DevServerBridgeOptions } from "@leadconnector/vite-plugin-dev-server-bridge";
import type { HmrGateOptions } from "@leadconnector/vite-plugin-hmr-gate";
import { componentTagger } from "@leadconnector/vibe-tagger";
import { resolve } from "node:path";
import {
  loadEnv,
  mergeConfig,
  type ConfigEnv,
  type PluginOption,
  type UserConfig,
} from "vite";
import {
  BUNDLED_DEV_ENV_VAR,
  bundledDevCssUrlShim,
  bundledDevRequested,
  resolveInstalledViteVersion,
  stripRedundantNodejsCompatFlag,
  viteVersionSupportsBundledDev,
} from "./bundledDev";
import {
  createBuildErrorDiagnostics,
  createServerFnErrorLogger,
  createSsrErrorLogger,
} from "./diagnostics";
import { isSandboxEnvironment } from "./env";
import { buildNitroOptions, loadNitroPlugin, shouldRunNitro } from "./nitro";
import {
  applyNonSandboxWatchDefaults,
  applySandboxServerInvariants,
} from "./server";

export interface LeadConnectorViteTanstackOptions {
  plugins?: PluginOption[];
  vite?: UserConfig;
  nitro?: true | false | Record<string, unknown>;
  tanstackStart?: Record<string, unknown>;
  react?: Record<string, unknown>;
  envDefine?: boolean;
  hmrGate?: boolean | HmrGateOptions;
  devServerBridge?: boolean | DevServerBridgeOptions;
  ssrErrorLogger?: boolean;
  serverFnErrorLogger?: boolean;
}

type ConfigFactory = (env: ConfigEnv) => UserConfig | Promise<UserConfig>;
type ViteConfigInput = UserConfig | ConfigFactory | Promise<UserConfig>;
type DefineConfigInput = LeadConnectorViteTanstackOptions | ViteConfigInput;

const OPTION_KEYS = new Set([
  "vite",
  "nitro",
  "tanstackStart",
  "react",
  "envDefine",
  "hmrGate",
  "devServerBridge",
  "ssrErrorLogger",
  "serverFnErrorLogger",
]);

const DEFAULT_IMPORT_PROTECTION = {
  behavior: "error",
  client: {
    files: ["**/server/**"],
    specifiers: ["server-only"],
  },
};

const DEFAULT_DEDUPE = [
  "react",
  "react-dom",
  "react/jsx-runtime",
  "react/jsx-dev-runtime",
  "@tanstack/react-query",
  "@tanstack/query-core",
];

const DEFAULT_OPTIMIZE_DEPS = [
  "react",
  "react-dom",
  "react-dom/client",
  "react/jsx-runtime",
  "react/jsx-dev-runtime",
];

function logWarning(message: string): void {
  console.warn(`[@leadconnector/vite-tanstack-config] ${message}`);
}

function isPromiseLike(value: unknown): value is Promise<UserConfig> {
  return (
    !!value &&
    (typeof value === "object" || typeof value === "function") &&
    typeof (value as { then?: unknown }).then === "function"
  );
}

function isExplicitOptions(value: Record<string, unknown>): boolean {
  return Object.keys(value).some((key) => OPTION_KEYS.has(key));
}

async function normalizeOptions(
  input: DefineConfigInput,
  env: ConfigEnv,
): Promise<LeadConnectorViteTanstackOptions> {
  if (typeof input === "function") {
    return { vite: await Promise.resolve(input(env)) };
  }
  if (isPromiseLike(input)) return { vite: await input };
  const object =
    input && typeof input === "object"
      ? (input as Record<string, unknown>)
      : {};
  return isExplicitOptions(object)
    ? (object as LeadConnectorViteTanstackOptions)
    : { vite: object as UserConfig };
}

function pluginEnabled(
  option: boolean | object | undefined,
  isSandbox: boolean,
): boolean {
  return isSandbox ? option !== false : option === true || !!option;
}

function pluginOptions<T extends object>(
  option: boolean | T | undefined,
): T | Record<string, never> {
  return option && typeof option === "object" ? option : {};
}

function platformDevServerBridgeOptions(
  option: boolean | DevServerBridgeOptions | undefined,
  isSandbox: boolean,
): DevServerBridgeOptions {
  const configured = pluginOptions(option) as DevServerBridgeOptions;
  if (
    !isSandbox ||
    !configured.errorCollector ||
    typeof configured.errorCollector !== "object"
  ) {
    return configured;
  }
  return {
    ...configured,
    errorCollector: {
      ...configured.errorCollector,
      endpoint: "/__vibe/error-collector",
    },
  };
}

function withUserAliasPrecedence(
  config: UserConfig,
  userConfig: UserConfig,
): UserConfig {
  const userAlias = userConfig.resolve?.alias;
  if (!userAlias) return config;

  if (Array.isArray(userAlias)) {
    const userAtAliases = userAlias.filter((entry) => entry.find === "@");
    if (userAtAliases.length === 0) return config;
    const merged = Array.isArray(config.resolve?.alias)
      ? config.resolve.alias
      : Object.entries(config.resolve?.alias ?? {}).map(
          ([find, replacement]) => ({ find, replacement }),
        );
    return {
      ...config,
      resolve: {
        ...config.resolve,
        alias: [
          ...userAtAliases,
          ...merged.filter((entry) => entry.find !== "@"),
        ],
      },
    };
  }

  const userAliasRecord = userAlias as Record<string, string>;
  if (!Object.prototype.hasOwnProperty.call(userAliasRecord, "@"))
    return config;
  const mergedAlias = Array.isArray(config.resolve?.alias)
    ? config.resolve.alias.filter((entry) => entry.find !== "@")
    : config.resolve?.alias;
  return {
    ...config,
    resolve: {
      ...config.resolve,
      alias: Array.isArray(mergedAlias)
        ? [{ find: "@", replacement: userAliasRecord["@"] }, ...mergedAlias]
        : { ...mergedAlias, "@": userAliasRecord["@"] },
    },
  };
}

export function defineConfig(): ConfigFactory;
export function defineConfig(
  options: LeadConnectorViteTanstackOptions,
): ConfigFactory;
export function defineConfig(config: UserConfig): ConfigFactory;
export function defineConfig(config: ConfigFactory): ConfigFactory;
export function defineConfig(config: Promise<UserConfig>): ConfigFactory;
export function defineConfig(
  configOrOptions: DefineConfigInput = {},
): ConfigFactory {
  return async (env: ConfigEnv): Promise<UserConfig> => {
    const { command, mode } = env;
    const isSandbox = isSandboxEnvironment();
    const options = await normalizeOptions(configOrOptions, env);
    const internalPlugins: PluginOption[] = [];

    if (mode === "development") {
      // FIRST: TanStack's official source instrumentation. Its inject-source
      // plugin is enforce:'pre' and, being first in the array, transforms the
      // ORIGINAL route module before tanstackStart's splitter — so
      // data-tsd-source carries canonical file:line:col (file cwd-relative
      // with leading slash, 1-indexed line, 1-indexed column of "<" which
      // numerically equals the pipeline's 0-indexed tag-name column). Every
      // devtools feature except injectSource is disabled — the identical flag
      // set used by the upstream TanStack configuration. Its own `apply`
      // additionally gates to development mode.
      const { devtools } = await import("@tanstack/devtools-vite");
      internalPlugins.push(
        devtools({
          logging: false,
          eventBusConfig: { enabled: false },
          enhancedLogs: { enabled: false },
          consolePiping: { enabled: false },
          removeDevtoolsOnBuild: false,
          injectSource: { enabled: true },
        }),
      );
    }

    // Tagger: keeps the __jsxSource__/sourceElementMap runtime (the handler's
    // second-priority fallback) and the tailwind config extraction the theme
    // flow depends on. Canonical source positions come from data-tsd-source
    // (@tanstack/devtools-vite), which supersedes the removed sourceInjection
    // transform (research: vibe-platform repo,
    // docs/superpowers/research/2026-07-22-visual-edits-tsd-source-parity.md).
    if (command === "serve" && mode === "development") {
      internalPlugins.push(
        componentTagger({ jsxSource: true, tailwindConfig: true }),
      );
    }

    const tailwindcss = (await import("@tailwindcss/vite")).default;
    const tsConfigPaths = (await import("vite-tsconfig-paths")).default;
    internalPlugins.push(tailwindcss());
    internalPlugins.push(tsConfigPaths({ projects: ["./tsconfig.json"] }));
    if (options.serverFnErrorLogger !== false) {
      internalPlugins.push(createServerFnErrorLogger());
    }
    if (options.ssrErrorLogger !== false) {
      internalPlugins.push(createSsrErrorLogger());
    }
    if (command === "build" && isSandbox) {
      internalPlugins.push(createBuildErrorDiagnostics());
    }

    const { tanstackStart } = await import("@tanstack/react-start/plugin/vite");
    const tanstackStartOptions = mergeConfig(
      { importProtection: DEFAULT_IMPORT_PROTECTION },
      options.tanstackStart ?? {},
    );
    internalPlugins.push(tanstackStart(tanstackStartOptions));

    if (
      shouldRunNitro(command as "build" | "serve", options.nitro, isSandbox)
    ) {
      const requiredReason =
        options.nitro === true ||
        (typeof options.nitro === "object" && options.nitro !== null)
          ? "an explicit `nitro` option was set"
          : "running inside a Vibe sandbox";
      const nitroFn = await loadNitroPlugin(
        // nitro is an optional peer dependency, so keep the import dynamic.
        // @ts-expect-error -- optional peer types are intentionally unavailable.
        () => import("nitro/vite"),
        requiredReason,
      );
      const nitroOptions = buildNitroOptions(options.nitro, isSandbox);
      internalPlugins.push(nitroFn(nitroOptions) as PluginOption);
      if (isSandbox) {
        const output = nitroOptions.output as { serverDir?: unknown } | undefined;
        internalPlugins.push(
          stripRedundantNodejsCompatFlag(
            typeof output?.serverDir === "string"
              ? output.serverDir
              : "dist/server",
          ),
        );
      }
    }

    const viteReact = (await import("@vitejs/plugin-react")).default;
    internalPlugins.push(viteReact(options.react ?? {}));

    if (command === "serve" && pluginEnabled(options.hmrGate, isSandbox)) {
      const { hmrGatePlugin } =
        await import("@leadconnector/vite-plugin-hmr-gate");
      internalPlugins.push(
        hmrGatePlugin(pluginOptions(options.hmrGate) as HmrGateOptions),
      );
    }
    if (
      command === "serve" &&
      pluginEnabled(options.devServerBridge, isSandbox)
    ) {
      const { devServerBridgePlugin } =
        await import("@leadconnector/vite-plugin-dev-server-bridge");
      internalPlugins.push(
        devServerBridgePlugin(
          platformDevServerBridgeOptions(options.devServerBridge, isSandbox),
        ),
      );
    }

    const userConfig = options.vite ?? {};
    const projectRoot = resolve(process.cwd(), userConfig.root ?? ".");
    const envDirectory =
      userConfig.envDir === false
        ? undefined
        : resolve(projectRoot, userConfig.envDir ?? ".");
    const envDefine: Record<string, string> = {};
    if (options.envDefine !== false && envDirectory) {
      const loadedEnv = loadEnv(mode, envDirectory, "VITE_");
      for (const [key, value] of Object.entries(loadedEnv)) {
        envDefine[`import.meta.env.${key}`] = JSON.stringify(value);
      }
    }

    const isDevBuild = command === "build" && mode === "development";
    const baseConfig: UserConfig = {
      define: {
        ...envDefine,
        ...(isDevBuild
          ? {
              "process.env.NODE_ENV": JSON.stringify("development"),
            }
          : {}),
      },
      ...(isDevBuild
        ? {
            environments: {
              client: {
                define: {
                  "process.env.NODE_ENV": JSON.stringify("development"),
                },
              },
            },
            esbuild: { keepNames: true },
          }
        : {}),
      css: { transformer: "lightningcss" },
      resolve: {
        alias: { "@": resolve(projectRoot, "src") },
        dedupe: DEFAULT_DEDUPE,
      },
      optimizeDeps: {
        include: DEFAULT_OPTIMIZE_DEPS,
        ignoreOutdatedRequests: true,
      },
      plugins: [...internalPlugins, ...(options.plugins ?? [])],
      server: { host: "::", port: 8080 },
    };

    let config = mergeConfig(baseConfig, userConfig);
    config = withUserAliasPrecedence(config, userConfig);

    if (command === "serve" && isSandbox && bundledDevRequested()) {
      const viteVersion = resolveInstalledViteVersion(projectRoot);
      if (viteVersionSupportsBundledDev(viteVersion)) {
        config = mergeConfig(config, {
          experimental: { bundledDev: true },
          plugins: [bundledDevCssUrlShim()],
        });
      } else {
        logWarning(
          `Bundled dev requested (${BUNDLED_DEV_ENV_VAR}=true), but installed ` +
            `Vite ${viteVersion ?? "unresolved"} is missing, prerelease, or below ` +
            "8.1. Starting classic dev.",
        );
      }
    }

    return isSandbox
      ? applySandboxServerInvariants(config)
      : applyNonSandboxWatchDefaults(config);
  };
}
