import type { Plugin, ViteDevServer } from "vite";

const SSR_CAPTURE_KEY = "__VIBE_TANSTACK_CAPTURE_SSR_ERROR__";
const HANDLER_RAN_KEY = "__VIBE_TANSTACK_HANDLER_RAN__";
const SERVER_FN_SEND_KEY = "__VIBE_TANSTACK_SERVER_FN_HMR_SEND__";
const MAX_JSON_LENGTH = 6_000;
const MAX_STRING_LENGTH = 2_000;
const MAX_ITEMS = 20;
const MAX_DEPTH = 4;
const ERROR_FIELDS = [
  "name",
  "message",
  "plugin",
  "pluginCode",
  "id",
  "moduleId",
  "hook",
  "code",
  "loc",
  "frame",
  "stack",
  "cause",
] as const;

function truncate(value: string, max = MAX_STRING_LENGTH): string {
  return value.length > max ? `${value.slice(0, max)}...[truncated]` : value;
}

function readProperty(value: object, key: string): unknown {
  try {
    return (value as Record<string, unknown>)[key];
  } catch (error) {
    return `[unreadable: ${
      error instanceof Error ? error.message : String(error)
    }]`;
  }
}

function describePrimitive(value: unknown): string {
  if (typeof value === "symbol") {
    return value.description ? `Symbol(${value.description})` : "Symbol()";
  }
  if (typeof value === "function") {
    return `[function ${value.name || "anonymous"}]`;
  }
  return String(value);
}

function serializeDiagnosticValue(
  value: unknown,
  depth = 0,
  seen = new WeakSet<object>(),
): unknown {
  if (value == null) return value;
  if (typeof value === "string") return truncate(value);
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (typeof value !== "object") return describePrimitive(value);
  if (seen.has(value)) return "[circular]";
  if (depth >= MAX_DEPTH) return "[max depth]";

  seen.add(value);
  try {
    if (Array.isArray(value)) {
      const entries = value
        .slice(0, MAX_ITEMS)
        .map((entry) => serializeDiagnosticValue(entry, depth + 1, seen));
      if (value.length > MAX_ITEMS) {
        entries.push(`[${value.length - MAX_ITEMS} items truncated]`);
      }
      return entries;
    }

    const output: Record<string, unknown> = {};
    for (const field of ERROR_FIELDS) {
      if (!(field in value)) continue;
      const nested = readProperty(value, field);
      if (nested == null || nested === "") continue;
      output[field] = serializeDiagnosticValue(nested, depth + 1, seen);
    }
    const nestedErrors = readProperty(value, "errors");
    if (nestedErrors != null && nestedErrors !== "") {
      output.errors = serializeDiagnosticValue(
        Array.isArray(nestedErrors)
          ? nestedErrors.slice(0, MAX_ITEMS)
          : nestedErrors,
        depth + 1,
        seen,
      );
    }
    if (Object.keys(output).length > 0) return output;

    const keys = Object.keys(value);
    for (const key of keys.slice(0, MAX_ITEMS)) {
      const nested = readProperty(value, key);
      if (nested == null || nested === "") continue;
      output[truncate(key, 200)] = serializeDiagnosticValue(
        nested,
        depth + 1,
        seen,
      );
    }
    if (keys.length > MAX_ITEMS) {
      output.properties_truncated = keys.length - MAX_ITEMS;
    }
    return Object.keys(output).length > 0
      ? output
      : Object.prototype.toString.call(value);
  } catch (error) {
    return `[unreadable object: ${
      error instanceof Error ? error.message : String(error)
    }]`;
  } finally {
    seen.delete(value);
  }
}

export function stringifyDiagnosticPayload(value: unknown): string {
  const serialized = serializeDiagnosticValue(value);
  const full = JSON.stringify(serialized);
  if (full.length <= MAX_JSON_LENGTH) return full;

  const compact = serializeDiagnosticValue(value, 2);
  const compactPayload =
    compact && typeof compact === "object" && !Array.isArray(compact)
      ? { ...compact, diagnostics_truncated: true }
      : { diagnostics_truncated: true, value: compact };
  const compactJson = JSON.stringify(compactPayload);
  if (compactJson.length <= MAX_JSON_LENGTH) return compactJson;
  return JSON.stringify({
    diagnostics_truncated: true,
    message: "Diagnostic payload exceeded output budget.",
  });
}

function boundedData(value: unknown): Record<string, unknown> {
  try {
    const parsed = JSON.parse(stringifyDiagnosticPayload(value)) as unknown;
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : { value: parsed };
  } catch {
    return { message: "Diagnostic payload could not be serialized." };
  }
}

export function createBuildErrorDiagnostics(): Plugin {
  let emitted = false;
  const emit = (error: unknown): void => {
    if (!error || emitted) return;
    emitted = true;
    try {
      const output = `\n[vibe-build-error-diagnostics]\n${stringifyDiagnosticPayload(
        error,
      )}\n[/vibe-build-error-diagnostics]\n`;
      let written = false;
      const write = (): void => {
        if (written) return;
        written = true;
        try {
          process.stderr.write(output);
        } catch {
          // Diagnostics must never replace the original build error.
        }
      };
      // Vite often process.exit()s right after a failed build, which can
      // drop a synchronous stderr.write. Defer to the next turn and also
      // latch onto exit so a crashing build still emits the marker.
      setImmediate(write);
      process.once("exit", write);
    } catch {
      // Diagnostics must never replace the original build error.
    }
  };
  return {
    name: "vibe-build-error-diagnostics",
    apply: "build",
    buildEnd: emit,
    renderError: emit,
  };
}

function isEsbuildMessageArray(errors: unknown): boolean {
  return (
    Array.isArray(errors) &&
    errors.length > 0 &&
    errors.every(
      (entry) =>
        entry != null &&
        typeof entry === "object" &&
        "text" in entry &&
        "location" in entry,
    )
  );
}

export function isBuildError(error: unknown): boolean {
  const messagePattern =
    /transform failed with \d+ error|failed to parse source/i;
  if (typeof error === "string") return messagePattern.test(error);
  if (!error || typeof error !== "object") return false;
  const record = error as Record<string, unknown>;
  if (
    typeof record.plugin === "string" &&
    (record.plugin.startsWith("vite:") ||
      record.plugin.startsWith("esbuild:"))
  ) {
    return true;
  }
  if (record.frame != null && record.loc != null) return true;
  if (isEsbuildMessageArray(record.errors)) return true;
  return (
    typeof record.message === "string" && messagePattern.test(record.message)
  );
}

function isRequestResponseModule(id: string): boolean {
  const normalized = id.replaceAll("\\", "/").split("?")[0];
  return (
    normalized.includes(
      "/@tanstack/start-server-core/src/request-response.ts",
    ) ||
    normalized.includes(
      "/@tanstack/start-server-core/dist/esm/request-response.js",
    )
  );
}

function isServerFunctionsHandlerModule(id: string): boolean {
  const normalized = id.replaceAll("\\", "/").split("?")[0];
  return (
    normalized.includes(
      "/@tanstack/start-server-core/src/server-functions-handler.ts",
    ) ||
    normalized.includes(
      "/@tanstack/start-server-core/dist/esm/server-functions-handler.js",
    )
  );
}

type RuntimeGlobal = typeof globalThis & Record<string, unknown>;
type GlobalSnapshot = { existed: boolean; value: unknown };
type SsrGlobalRegistration = {
  capture: (error: unknown, event: unknown) => void;
  mark: (event: unknown) => void;
};
type ServerFnGlobalRegistration = {
  dispatch: (data: unknown) => void;
};

const runtimeGlobal = globalThis as RuntimeGlobal;
const ssrGlobalRegistrations: SsrGlobalRegistration[] = [];
const serverFnGlobalRegistrations: ServerFnGlobalRegistration[] = [];
let originalSsrCapture: GlobalSnapshot | undefined;
let originalSsrMark: GlobalSnapshot | undefined;
let originalServerFnSend: GlobalSnapshot | undefined;

function snapshotGlobal(key: string): GlobalSnapshot {
  return {
    existed: Object.prototype.hasOwnProperty.call(runtimeGlobal, key),
    value: runtimeGlobal[key],
  };
}

function restoreGlobal(key: string, snapshot: GlobalSnapshot): void {
  if (snapshot.existed) runtimeGlobal[key] = snapshot.value;
  else delete runtimeGlobal[key];
}

function registerSsrGlobals(registration: SsrGlobalRegistration): void {
  if (ssrGlobalRegistrations.length === 0) {
    originalSsrCapture = snapshotGlobal(SSR_CAPTURE_KEY);
    originalSsrMark = snapshotGlobal(HANDLER_RAN_KEY);
  }
  ssrGlobalRegistrations.push(registration);
  runtimeGlobal[SSR_CAPTURE_KEY] = registration.capture;
  runtimeGlobal[HANDLER_RAN_KEY] = registration.mark;
}

function unregisterSsrGlobals(registration: SsrGlobalRegistration): void {
  const index = ssrGlobalRegistrations.indexOf(registration);
  if (index === -1) return;
  ssrGlobalRegistrations.splice(index, 1);
  const active = ssrGlobalRegistrations.at(-1);
  if (active) {
    runtimeGlobal[SSR_CAPTURE_KEY] = active.capture;
    runtimeGlobal[HANDLER_RAN_KEY] = active.mark;
    return;
  }
  restoreGlobal(SSR_CAPTURE_KEY, originalSsrCapture!);
  restoreGlobal(HANDLER_RAN_KEY, originalSsrMark!);
  originalSsrCapture = undefined;
  originalSsrMark = undefined;
}

function registerServerFnGlobal(
  registration: ServerFnGlobalRegistration,
): void {
  if (serverFnGlobalRegistrations.length === 0) {
    originalServerFnSend = snapshotGlobal(SERVER_FN_SEND_KEY);
  }
  serverFnGlobalRegistrations.push(registration);
  runtimeGlobal[SERVER_FN_SEND_KEY] = registration.dispatch;
}

function unregisterServerFnGlobal(
  registration: ServerFnGlobalRegistration,
): void {
  const index = serverFnGlobalRegistrations.indexOf(registration);
  if (index === -1) return;
  serverFnGlobalRegistrations.splice(index, 1);
  const active = serverFnGlobalRegistrations.at(-1);
  if (active) {
    runtimeGlobal[SERVER_FN_SEND_KEY] = active.dispatch;
    return;
  }
  restoreGlobal(SERVER_FN_SEND_KEY, originalServerFnSend!);
  originalServerFnSend = undefined;
}

export function createSsrErrorLogger(): Plugin {
  const handlerRan = Symbol("vibeHandlerRan");
  const capturedError = Symbol("vibeCapturedSsrError");
  type Generation = {
    close: () => void;
    httpServer?: NonNullable<ViteDevServer["httpServer"]>;
  };
  const generations: Generation[] = [];
  let globalsInstalled = false;

  const responseFromEvent = (
    event: unknown,
  ): Record<PropertyKey, unknown> | undefined => {
    const response = (
      event as { node?: { res?: unknown } } | undefined
    )?.node?.res;
    return response && typeof response === "object"
      ? (response as Record<PropertyKey, unknown>)
      : undefined;
  };
  const capture = (error: unknown, event: unknown): void => {
    const response = responseFromEvent(event);
    if (!response) return;
    response[handlerRan] = true;
    response[capturedError] = error;
  };
  const consumeCapture = (
    response: Record<PropertyKey, unknown>,
  ): unknown => {
    const error = response[capturedError];
    delete response[capturedError];
    return error;
  };
  const markHandlerRan = (event: unknown): void => {
    const response = responseFromEvent(event);
    if (response) response[handlerRan] = true;
  };
  const registration = { capture, mark: markHandlerRan };
  const installGlobals = (): void => {
    if (globalsInstalled) return;
    registerSsrGlobals(registration);
    globalsInstalled = true;
  };
  const restoreGlobals = (): void => {
    if (!globalsInstalled || generations.length > 0) return;
    globalsInstalled = false;
    unregisterSsrGlobals(registration);
  };
  const retireOldestDetached = (): void => {
    generations.find((generation) => !generation.httpServer)?.close();
  };

  return {
    name: "vibe-ssr-error-logger",
    apply: "serve",
    configureServer(server: ViteDevServer) {
      installGlobals();
      const httpServer = server.httpServer;
      let closed = false;
      const generation = {} as Generation;
      const cleanup = (): void => {
        if (closed) return;
        closed = true;
        httpServer?.off("close", cleanup);
        const index = generations.indexOf(generation);
        if (index !== -1) generations.splice(index, 1);
        restoreGlobals();
      };
      generation.close = cleanup;
      generation.httpServer = httpServer ?? undefined;
      generations.push(generation);
      httpServer?.once("close", cleanup);

      server.middlewares.use((request, response, next) => {
        let handled = false;
        const handleErrorResponse = (): void => {
          if (handled || response.statusCode < 500) return;
          handled = true;
          const responseRecord = response as unknown as Record<
            PropertyKey,
            unknown
          >;
          const captured = consumeCapture(responseRecord);
          const ranHandler = Boolean(responseRecord[handlerRan]);
          const source = !ranHandler
            ? "vite"
            : isBuildError(captured)
              ? "build"
              : "app";
          if (!response.headersSent) {
            try {
              response.setHeader("x-vibe-error-source", source);
            } catch {
              // The response may have become immutable.
            }
          }
          const where =
            [request.method, request.url].filter(Boolean).join(" ") ||
            "the request";
          const data =
            captured !== undefined
              ? boundedData(captured)
              : {
                  message: ranHandler
                    ? `The app returned ${response.statusCode} while handling ${where}, but no stack was captured.`
                    : `The dev server returned ${response.statusCode} for ${where} before the app handler ran.`,
                };
          try {
            server.ws.send({
              type: "custom",
              event: "vibe:server-ssr-error",
              data,
            });
          } catch {
            // A disconnected diagnostics channel must not affect the response.
          }
        };
        const writeHead = response.writeHead.bind(response);
        response.writeHead = ((...args: Parameters<typeof response.writeHead>) => {
          if (typeof args[0] === "number") response.statusCode = args[0];
          handleErrorResponse();
          return writeHead(...args);
        }) as typeof response.writeHead;
        const end = response.end.bind(response);
        response.end = ((...args: Parameters<typeof response.end>) => {
          handleErrorResponse();
          return end(...args);
        }) as typeof response.end;
        next();
      });
    },
    transform(code, id) {
      if (!isRequestResponseModule(id)) return null;
      if (code.includes(SSR_CAPTURE_KEY)) return null;
      const needle = "handler(request, requestOpts)";
      if (!code.includes(needle)) {
        throw new Error(
          "[@leadconnector/vite-tanstack-config] unsupported " +
            "@tanstack/start-server-core request-response transform: " +
            `expected ${JSON.stringify(needle)} in ${id}.`,
        );
      }
      return code.replace(
        needle,
        `(() => {
          const __vibeSsrEvent = typeof h3Event === "undefined" ? undefined : h3Event
          globalThis.${HANDLER_RAN_KEY}?.(__vibeSsrEvent)
          try {
            return Promise.resolve(${needle}).catch((err) => {
              globalThis.${SSR_CAPTURE_KEY}?.(err, __vibeSsrEvent)
              throw err
            })
          } catch (err) {
            globalThis.${SSR_CAPTURE_KEY}?.(err, __vibeSsrEvent)
            throw err
          }
        })()`,
      );
    },
    closeWatcher() {},
    closeBundle() {
      retireOldestDetached();
    },
  };
}

export function createServerFnErrorLogger(): Plugin {
  type Generation = {
    close: () => void;
    httpServer?: NonNullable<ViteDevServer["httpServer"]>;
    send: (data: unknown) => void;
  };
  const generations: Generation[] = [];
  let globalInstalled = false;
  const dispatch = (data: unknown): void => {
    generations.at(-1)?.send(data);
  };
  const registration = { dispatch };
  const installGlobal = (): void => {
    if (globalInstalled) return;
    registerServerFnGlobal(registration);
    globalInstalled = true;
  };
  const restoreGlobal = (): void => {
    if (!globalInstalled || generations.length > 0) return;
    globalInstalled = false;
    unregisterServerFnGlobal(registration);
  };
  const retireOldestDetached = (): void => {
    generations.find((generation) => !generation.httpServer)?.close();
  };
  return {
    name: "vibe-server-fn-error-logger",
    apply: "serve",
    enforce: "pre",
    configureServer(server) {
      installGlobal();
      const send = (data: unknown): void => {
        try {
          server.ws.send({
            type: "custom",
            event: "vibe:server-fn-error",
            data: boundedData(data),
          });
        } catch {
          // Diagnostics must not alter server-function behavior.
        }
      };
      const httpServer = server.httpServer;
      let closed = false;
      const generation = {} as Generation;
      const cleanup = (): void => {
        if (closed) return;
        closed = true;
        httpServer?.off("close", cleanup);
        const index = generations.indexOf(generation);
        if (index !== -1) generations.splice(index, 1);
        restoreGlobal();
      };
      generation.close = cleanup;
      generation.httpServer = httpServer ?? undefined;
      generation.send = send;
      generations.push(generation);
      httpServer?.once("close", cleanup);
    },
    transform(code, id) {
      if (!isServerFunctionsHandlerModule(id)) return null;
      if (code.includes(SERVER_FN_SEND_KEY)) return null;
      const needle = "const unwrapped = res.result || res.error";
      if (!code.includes(needle)) {
        throw new Error(
          "[@leadconnector/vite-tanstack-config] unsupported " +
            "@tanstack/start-server-core server-functions-handler " +
            `transform: expected ${JSON.stringify(needle)} in ${id}.`,
        );
      }
      return code.replace(
        needle,
        `${needle}

      if (res?.error) {
        const err = res.error
        const clipVibeDiagnostic = (value, max = 2000) => {
          let text
          try { text = String(value ?? "") } catch { text = "[unreadable]" }
          return text.length > max ? text.slice(0, max) + "...[truncated]" : text
        }
        globalThis.${SERVER_FN_SEND_KEY}?.({
          source: "tanstack",
          type: "vibe:server-fn-error",
          method: clipVibeDiagnostic(request.method, 32),
          url: clipVibeDiagnostic(request.url, 1000),
          name: clipVibeDiagnostic(err?.name ?? "Error", 200),
          message: clipVibeDiagnostic(err?.message ?? err),
          stack: typeof err?.stack === "string" ? clipVibeDiagnostic(err.stack) : undefined,
        })
      }`,
      );
    },
    closeWatcher() {},
    closeBundle() {
      retireOldestDetached();
    },
  };
}
