export function shouldRunNitro(command: "build" | "serve", nitroOpt: unknown, isSandbox: boolean): boolean {
  const explicit = nitroOpt === true || (typeof nitroOpt === "object" && nitroOpt !== null);
  return nitroOpt !== false && command === "build" && (explicit || isSandbox);
}

export function buildNitroOptions(nitroOpt: unknown, isSandbox: boolean): Record<string, unknown> {
  const user = typeof nitroOpt === "object" && nitroOpt ? (nitroOpt as Record<string, unknown>) : {};
  const opts: Record<string, unknown> = { defaultPreset: "cloudflare-module", ...user };
  if (isSandbox) {
    delete opts.defaultPreset;
    opts.preset = "cloudflare-module";
    opts.output = { dir: "dist", serverDir: "dist/server", publicDir: "dist/client" };
    opts.cloudflare = { nodeCompat: true, deployConfig: true, ...(user.cloudflare as object | undefined) };
  }
  return opts;
}

type NitroModule = Record<string, unknown>;
type NitroImporter = () => Promise<NitroModule>;

export async function loadNitroPlugin(
  importer: NitroImporter,
  requiredReason: string,
): Promise<(options: unknown) => unknown> {
  let nitroModule: NitroModule;
  try {
    nitroModule = await importer();
  } catch (error) {
    throw new Error(
      `[@leadconnector/vite-tanstack-config] ${requiredReason}, but the ` +
        "`nitro` package could not be loaded. Install `nitro` in devDependencies " +
        `(peerDependency >=3.0.260603-beta). Original import error: ${
          error instanceof Error ? error.message : String(error)
        }`,
      { cause: error },
    );
  }

  const nitro = nitroModule.nitro;
  if (typeof nitro !== "function") {
    throw new Error(
      "[@leadconnector/vite-tanstack-config] could not resolve the Nitro " +
        "plugin (expected a named `nitro` export from `nitro/vite`). " +
        `Installed exports: ${Object.keys(nitroModule).join(", ") || "(none)"}.`,
    );
  }
  return nitro as (options: unknown) => unknown;
}
