import { createRequire } from "node:module";
import { readFile, writeFile } from "node:fs/promises";
import { isAbsolute, join, resolve } from "node:path";
import type { Plugin } from "vite";

export const BUNDLED_DEV_ENV_VAR = "VIBE_FEATURE_BUNDLED_DEV";
const CSS_URL_VIRTUAL_PREFIX = "\0vibe-bundled-dev-css-url:";
const CSS_URL_VIRTUAL_SUFFIX = ".shim.js";
const NODEJS_COMPAT_DEFAULT_ON_DATE = "2026-08-04";
const DEFAULT_SANDBOX_SERVER_DIR = "dist/server";

export function bundledDevRequested(): boolean {
  return process.env[BUNDLED_DEV_ENV_VAR] === "true";
}

export function viteVersionSupportsBundledDev(
  version: string | undefined,
): boolean {
  if (!version || version.includes("-")) return false;
  const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(version);
  if (!match) return false;
  const major = Number(match[1]);
  const minor = Number(match[2]);
  return major > 8 || (major === 8 && minor >= 1);
}

export function resolveInstalledViteVersion(
  cwd = process.cwd(),
): string | undefined {
  try {
    const manifest = createRequire(`${cwd}/package.json`)(
      "vite/package.json",
    ) as { version?: unknown };
    return typeof manifest.version === "string" ? manifest.version : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Bundled dev does not emit CSS assets for `?url` imports. Convert them to a
 * data URL backed by Vite's inline CSS transform so callers retain a URL.
 */
export function bundledDevCssUrlShim(): Plugin {
  return {
    name: "vibe-bundled-dev-css-url-shim",
    apply: "serve",
    enforce: "pre",
    async resolveId(id, importer) {
      if (!id.endsWith(".css?url")) return null;
      const resolved = await this.resolve(id.slice(0, -4), importer, {
        skipSelf: true,
      });
      return resolved
        ? `${CSS_URL_VIRTUAL_PREFIX}${resolved.id}${CSS_URL_VIRTUAL_SUFFIX}`
        : null;
    },
    load(id) {
      if (
        !id.startsWith(CSS_URL_VIRTUAL_PREFIX) ||
        !id.endsWith(CSS_URL_VIRTUAL_SUFFIX)
      ) {
        return null;
      }
      const cssId = id.slice(
        CSS_URL_VIRTUAL_PREFIX.length,
        -CSS_URL_VIRTUAL_SUFFIX.length,
      );
      const inlineSpecifier = cssId.includes("?")
        ? `${cssId}&inline`
        : `${cssId}?inline`;
      return [
        `import css from ${JSON.stringify(inlineSpecifier)};`,
        'const b64 = typeof Buffer !== "undefined" ? Buffer.from(css, "utf8").toString("base64") : btoa(unescape(encodeURIComponent(css)));',
        'export default "data:text/css;base64," + b64;',
      ].join("\n");
    },
  };
}

/**
 * Workers enables nodejs_compat by default from the compatibility date below,
 * so Nitro's generated flag becomes redundant (and triggers Wrangler advice).
 */
function isCanonicalCompatibilityDate(value: string): boolean {
  return /^\d{4}-\d{2}-\d{2}$/.test(value);
}

export function stripRedundantNodejsCompatFlag(
  serverDir = DEFAULT_SANDBOX_SERVER_DIR,
): Plugin {
  let root = process.cwd();
  let warn = (message: string) => console.warn(message);
  return {
    name: "vibe-strip-redundant-nodejs-compat",
    apply: "build",
    configResolved(config) {
      root = config.root;
      if (typeof config.logger?.warn === "function") {
        warn = config.logger.warn.bind(config.logger);
      }
    },
    buildApp: {
      order: "post",
      async handler() {
        const configPath = join(
          isAbsolute(serverDir) ? serverDir : resolve(root, serverDir),
          "wrangler.json",
        );
        let parsed: unknown;
        try {
          parsed = JSON.parse(await readFile(configPath, "utf8"));
        } catch {
          return;
        }
        if (
          typeof parsed !== "object" ||
          parsed === null ||
          Array.isArray(parsed)
        ) {
          return;
        }
        const config = parsed as Record<string, unknown>;
        if (
          typeof config.compatibility_date !== "string" ||
          !isCanonicalCompatibilityDate(config.compatibility_date) ||
          config.compatibility_date < NODEJS_COMPAT_DEFAULT_ON_DATE ||
          !Array.isArray(config.compatibility_flags)
        ) {
          return;
        }
        const flags = config.compatibility_flags.filter(
          (flag) => flag !== "nodejs_compat",
        );
        if (flags.length === config.compatibility_flags.length) return;
        try {
          await writeFile(
            configPath,
            `${JSON.stringify({ ...config, compatibility_flags: flags }, null, 2)}\n`,
          );
        } catch {
          warn(
            `[@leadconnector/vite-tanstack-config] Unable to remove redundant nodejs_compat from ${configPath}; continuing with the generated configuration.`,
          );
        }
      },
    },
  };
}
