import { mergeConfig, type UserConfig } from "vite";

export const TOOL_MANAGED_WATCH_IGNORES = [
  "**/.workspace/**",
  "**/.agents/**",
  "**/.claude/**",
  "**/.lovable/**",
  "**/.tanstack/tmp/**",
];

type WatchIgnore =
  | string
  | RegExp
  | ((path: string, stats?: unknown) => boolean);
type WatchOptions = NonNullable<NonNullable<UserConfig["server"]>["watch"]> & {
  ignored?: WatchIgnore | WatchIgnore[];
};

const MAX_WARNING_ITEMS = 8;
const MAX_WARNING_LENGTH = 800;

function logWarning(message: string): void {
  const bounded =
    message.length > MAX_WARNING_LENGTH
      ? `${message.slice(0, MAX_WARNING_LENGTH)}...[truncated]`
      : message;
  console.warn(`[@leadconnector/vite-tanstack-config] ${bounded}`);
}

function boundedList(values: string[]): string {
  const shown = values.slice(0, MAX_WARNING_ITEMS);
  const omitted = values.length - shown.length;
  return `${shown.join(", ")}${omitted > 0 ? ` (+${omitted} more)` : ""}`;
}

function normalizeIgnored(value: unknown): WatchIgnore[] {
  if (
    typeof value === "string" ||
    typeof value === "function" ||
    value instanceof RegExp
  ) {
    return [value as WatchIgnore];
  }
  if (!Array.isArray(value)) return [];
  return value.filter(
    (entry): entry is WatchIgnore =>
      typeof entry === "string" ||
      typeof entry === "function" ||
      entry instanceof RegExp,
  );
}

function previewAllowedHosts(): string[] {
  const hosts = new Set<string>([".modal.host"]);
  const addHost = (value: string): void => {
    const trimmed = value.trim();
    if (!trimmed) return;
    try {
      const parsed = new URL(
        trimmed.includes("://") ? trimmed : `https://${trimmed}`,
      );
      if (!["http:", "https:"].includes(parsed.protocol)) throw new Error();
      if (parsed.username || parsed.password) throw new Error();
      const hostname = parsed.hostname.toLowerCase();
      const hostnameBody = hostname.startsWith(".")
        ? hostname.slice(1)
        : hostname;
      const validHostname =
        hostnameBody === "localhost" ||
        /^\[[0-9a-f:]+\]$/i.test(hostnameBody) ||
        hostnameBody.split(".").every(
          (label) =>
            label.length > 0 &&
            label.length <= 63 &&
            /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label),
        );
      if (!validHostname || hostname === "*") throw new Error();
      hosts.add(hostname);
    } catch {
      logWarning(`Ignoring invalid preview host ${JSON.stringify(trimmed)}.`);
    }
  };
  if (process.env.VIBE_PREVIEW_HOST) addHost(process.env.VIBE_PREVIEW_HOST);
  for (const host of (process.env.VIBE_PREVIEW_HOSTS ?? "").split(",")) {
    addHost(host);
  }
  return [...hosts];
}

const DEPRECATED_HMR_WEBSOCKET_KEYS = [
  "protocol",
  "host",
  "port",
  "path",
  "clientPort",
  "timeout",
  "server",
] as const;

// Vite 8 migrates these onto server.ws during mergeConfig, which both
// deprecates and can overwrite a user's explicit server.ws. Drop them
// before merging so sandbox HMR stays overlay-only.
function withoutDeprecatedHmrWebsocketOptions(config: UserConfig): UserConfig {
  const hmr = config.server?.hmr;
  if (hmr === false || hmr == null || typeof hmr !== "object") {
    return config;
  }
  const nextHmr = { ...(hmr as Record<string, unknown>) };
  let stripped = false;
  for (const key of DEPRECATED_HMR_WEBSOCKET_KEYS) {
    if (key in nextHmr) {
      delete nextHmr[key];
      stripped = true;
    }
  }
  if (!stripped) return config;
  return {
    ...config,
    server: {
      ...config.server,
      hmr: nextHmr,
    },
  };
}

function warnAndStripUnsupportedServerFields(config: UserConfig): UserConfig {
  const server = config.server;
  if (!server) return config;

  if (server.headers) {
    logWarning(
      `Sandbox mode removed unsupported server.headers: ${boundedList(
        Object.keys(server.headers),
      )}.`,
    );
  }
  if (server.cors !== undefined) {
    logWarning("Sandbox mode removed unsupported custom server.cors.");
  }
  if (server.proxy) {
    logWarning(
      `Sandbox mode removed unsupported server.proxy routes: ${boundedList(
        Object.keys(server.proxy),
      )}.`,
    );
  }

  if (
    server.headers === undefined &&
    server.cors === undefined &&
    server.proxy === undefined
  ) {
    return config;
  }
  const {
    headers: _headers,
    cors: _cors,
    proxy: _proxy,
    ...supportedServer
  } = server;
  return { ...config, server: supportedServer };
}

export function applyNonSandboxWatchDefaults(config: UserConfig): UserConfig {
  if (config.server?.watch === null) return config;
  return mergeConfig({
    server: {
      watch: {
        awaitWriteFinish: {
          stabilityThreshold: 1_000,
          pollInterval: 100,
        },
      },
    },
  }, config);
}

export function applySandboxServerInvariants(
  config: UserConfig,
): UserConfig {
  const userWatch = (config.server?.watch ?? {}) as WatchOptions;
  const ignored = [
    ...normalizeIgnored(userWatch.ignored),
    ...TOOL_MANAGED_WATCH_IGNORES,
  ];
  const dedupedIgnored = [...new Set(ignored)];
  const allowedHosts = previewAllowedHosts();
  // Sandbox HMR is overlay:false only. Vite 8 moved
  // protocol/host/port/path/clientPort/timeout/server to server.ws; do not
  // copy those onto server.hmr, and do not invent server.ws.timeout (Vite
  // already defaults that to 30s).
  const sanitized = withoutDeprecatedHmrWebsocketOptions(config);
  const userHmr = sanitized.server?.hmr;
  const sandboxHmr = userHmr === false ? false : { overlay: false };
  const merged = mergeConfig(sanitized, {
    server: {
      host: "::",
      port: 8080,
      strictPort: true,
      allowedHosts,
      watch: { ...userWatch, ignored: dedupedIgnored },
      hmr: sandboxHmr,
    },
  });

  // These assignments intentionally happen after mergeConfig. They are
  // sandbox invariants, not defaults, and therefore cannot be user-overridden.
  const mergedServer = merged.server ?? {};
  const invariantConfig: UserConfig = {
    ...merged,
    server: {
      ...mergedServer,
      host: "::",
      port: 8080,
      strictPort: true,
      allowedHosts,
      watch: {
        ...(mergedServer.watch as WatchOptions),
        ignored: dedupedIgnored,
      } as never,
      hmr: sandboxHmr,
    },
  };
  return warnAndStripUnsupportedServerFields(invariantConfig);
}
